CREATE TABLE IF NOT EXISTS fields_archive_m820_c4q AS SELECT * FROM fields WHERE false;
CREATE TABLE IF NOT EXISTS m820_c4q_written (tbl text NOT NULL, id uuid NOT NULL, md5 text NOT NULL, PRIMARY KEY (tbl, id));

