UPDATE fields f
   SET description = $m$PZ 6.3-1 (§6.3 Phasenziele, gedr. S. 14–15): Eine Vorzugsvariante aus der Variantenbetrachtung der Vorplanung ist vom Auftraggeber freigegeben und in die Entwurfsplanung fortgeführt. Bewerten Sie: Erreicht / Teilweise erreicht (löst die Projektstopp-Prüfung unten aus) / Nicht erreicht (blockiert bei Projekttyp Einzelprojekt oder Beides) / Nicht zutreffend / Phase noch nicht erreicht (nur wählen, wenn die Leistungsphase wirklich noch nicht abgeschlossen ist). Der Bewertungsblock dieses Blatts und von M8203-12 (QE 6.3 Teil 1) (Prüfer, Datum, Erfüllungsgrad, Zählungen Y/P/N/NA, Gesamtzahl) erscheint erst, wenn mindestens ein Phasenziel dieser Phase mit „Erreicht“, „Teilweise erreicht“ oder „Nicht erreicht“ bewertet ist; solange alle auf „Phase noch nicht erreicht“ oder „Nicht zutreffend“ stehen, bleibt er ausgeblendet (Werkzeug-Logik).
[EN] PZ 6.3-1 (§ 6.3 phase goals, printed p. 14–15): A preferred variant from the preliminary-design option study is approved by the client and carried forward into design planning. Rate it: Met / Partially met (triggers the Projektstopp review below) / Not met (blocks for project type einzelprojekt or both) / Not applicable / Phase not reached yet (choose only if the service phase genuinely has not closed). The assessment block of this sheet and of M8203-12 (QE 6.3 part 1) (assessor, date, fulfilment rate, Y/P/N/NA counts, total) appears only once at least one phase goal of this phase is rated "Met", "Partially met" or "Not met"; while all are "Phase not reached yet" or "Not applicable", it stays hidden (tool logic).$m$,
       consumer_worksheets = ARRAY['M8203-12', 'M8203-23', 'M8203-24']::text[]
  FROM worksheet_templates w, standards s
 WHERE f.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-13' AND f.symbol = 'pz_63_1_status' AND f.active
   AND md5(concat_ws('|', md5(coalesce(f.description,'')), coalesce(f.visible_when,''), coalesce(array_to_string(f.consumer_worksheets, ','),''), coalesce(md5(f.enum_values::text),''), f.label_de, coalesce(f.label_en,''), f.is_required::text, f.data_type, md5(coalesce(f.verification_quote,'')), coalesce(f.source_anchor,''))) = '5751fb1a7c23fd5f529951c9e86eee24';
